import styled from '@emotion/styled';

export const FooterActions = styled.div({
  display: 'flex',
  flexDirection: 'row',
  justifyContent: 'space-between',
  alignItems: 'center',
  gap: '12px',
  flexGrow: '1',
  height: '40px',
});

export const TriggerButton = styled.div({
  alignItems: 'center',
  background: '#ffffff',
  border: '1px solid #1414141f',
  borderRadius: '24px',
  color: '#141414',
  cursor: 'pointer',
  display: 'inline-flex',
  fontFamily: "'Work Sans', sans-serif",
  fontSize: '16px',
  fontWeight: '500',
  gap: '6px',
  minHeight: '40px',
  lineHeight: '140%',
  paddingLeft: '16px',
  paddingRight: '12px',
  width: 'fit-content',
  maxWidth: '310px',
  whiteSpace: 'nowrap',

  '&:focus-visible': {
    outline: '2px solid #006edb',
    outlineOffset: '2px',
  },
});

export const TriggerLabel = styled.span({
  color: '#141414',
  fontWeight: 500,
});

export const TriggerIcon = styled.span({
  color: '#6b7280',
  display: 'inline-flex',
  alignItems: 'center',
  padding: '0 8px',
});
